#!/usr/bin/env -S uv run --script
# /// script
# requires-python = ">=3.11"
# dependencies = []
# ///
"""
Keep the supported Python, PostgreSQL, Django and SQLAlchemy versions consistent.

The LATEST_* constants (kept up to date by Renovate) decide which versions are
supported. In the CI test matrix, instead of testing every combination, versions are
paired from oldest to newest, so that each is tested at least once.
"""

from __future__ import annotations

import argparse
import dataclasses
import json
import pathlib
import re
import sys
import tomllib

ROOT = pathlib.Path(__file__).parents[1]
README = ROOT / "README.md"
PYPROJECT = ROOT / "pyproject.toml"
PYTHON_VERSION = ROOT / ".python-version"
PRECOMMIT = ROOT / ".pre-commit-config.yaml"
DEVCONTAINER_DOCKERFILE = ROOT / ".devcontainer" / "Dockerfile"
DEVCONTAINER_COMPOSE = ROOT / ".devcontainer" / "docker-compose.yml"

# renovate: datasource=python-version depName=python
LATEST_PYTHON = "3.15"
# renovate: datasource=docker depName=postgres
LATEST_POSTGRES = "19"
# renovate: datasource=pypi depName=django
LATEST_DJANGO = "6.1"
# renovate: datasource=pypi depName=sqlalchemy
LATEST_SQLALCHEMY = "2.1"

PACKAGES = {"django": "django", "sqlalchemy": "sqlalchemy[asyncio]"}
GROUPS_COMMENT = "# Generated by .github/supported_versions.py\n"


def version_key(version: str) -> tuple[int, ...]:
    return tuple(int(part) for part in version.split("."))


def supported_python() -> list[str]:
    # https://devguide.python.org/versions/: a new version every year, supported
    # for 5 years.
    minor = version_key(LATEST_PYTHON)[1]
    return [f"3.{m}" for m in range(minor - 4, minor + 1)]


def supported_postgres() -> list[str]:
    # https://www.postgresql.org/support/versioning/: a new version every year,
    # supported for 5 years.
    latest = int(LATEST_POSTGRES)
    return [str(v) for v in range(latest - 4, latest + 1)]


def supported_django() -> list[str]:
    # https://docs.djangoproject.com/en/stable/internals/release-process/
    known = {
        "6.1": ["5.2", "6.0", "6.1"],
        "6.2": ["5.2", "6.1", "6.2"],
        "2028": ["6.2", "2028"],
        "2029": ["6.2", "2028", "2029"],
    }
    if LATEST_DJANGO in known:
        return known[LATEST_DJANGO]
    if not re.fullmatch(r"20\d\d", LATEST_DJANGO):
        sys.exit(
            f"Don't know which Django versions to support when {LATEST_DJANGO} is out"
        )
    year = int(LATEST_DJANGO)
    return [str(year - 2), str(year - 1), LATEST_DJANGO]


def supported_sqlalchemy(current: list[str]) -> list[str]:
    # https://www.sqlalchemy.org/download.html#relstatus: the latest series, and the
    # previous one in maintenance.
    older = [v for v in current if version_key(v) < version_key(LATEST_SQLALCHEMY)]
    return [*older[-1:], LATEST_SQLALCHEMY]


def current_groups() -> dict[str, list[str]]:
    """{package: [version]} from pyproject.toml, sorted from oldest to newest."""
    pyproject = tomllib.loads(PYPROJECT.read_text())
    groups: dict[str, list[str]] = {package: [] for package in PACKAGES}
    for name in pyproject["dependency-groups"]:
        if match := re.fullmatch(r"(django|sqlalchemy)-(\d+(?:-\d+)?)", name):
            groups[match.group(1)].append(match.group(2).replace("-", "."))
    return {package: sorted(v, key=version_key) for package, v in groups.items()}


def django_minimum_python(version: str) -> str:
    # https://docs.djangoproject.com/en/stable/faq/install/
    known = {"5.2": "3.10", "6.0": "3.12", "6.1": "3.12", "6.2": "3.12"}
    if version in known:
        return known[version]
    # From 2028: the Python version that moved to security fixes only when the alpha
    # came out, i.e. 3.14 for Django 2028.
    return f"3.{int(version) - 2014}"


def requirement(package: str, version: str) -> str:
    pin = f"{PACKAGES[package]}=={version}.*"
    if package == "django":
        needed = django_minimum_python(version)
        if version_key(needed) > version_key(supported_python()[0]):
            pin += f"; python_version >= '{needed}'"
    return pin


def group_name(package: str, version: str) -> str:
    return f"{package}-{version.replace('.', '-')}"


def rewrite(path: pathlib.Path, pattern: str, replacement: str) -> None:
    text = path.read_text()
    new, count = re.subn(pattern, lambda _: replacement, text, flags=re.MULTILINE)
    if count != 1:
        sys.exit(f"{path.name}: expected exactly one match for {pattern!r}")
    if new != text:
        path.write_text(new)
        print(f"{path.name}: updated")


def update_files() -> None:
    python = supported_python()
    postgres = supported_postgres()
    supported = {
        "django": supported_django(),
        "sqlalchemy": supported_sqlalchemy(current_groups()["sqlalchemy"]),
    }

    rewrite(PYTHON_VERSION, r"\A.*\n\Z", f"{LATEST_PYTHON}\n")
    rewrite(
        PYPROJECT, r'^requires-python = ".*"$', f'requires-python = ">={python[0]}"'
    )
    # The docs are built with the latest Python only.
    rewrite(
        PYPROJECT,
        r'^docs = \{ requires-python = ".*" \}$',
        f'docs = {{ requires-python = ">={LATEST_PYTHON}" }}',
    )
    rewrite(
        README,
        r'<span id="min-python">[^<]*</span>',
        f'<span id="min-python">{python[0]}</span>',
    )
    rewrite(
        README,
        r'<span id="min-postgres">[^<]*</span>',
        f'<span id="min-postgres">{postgres[0]}</span>',
    )
    rewrite(
        DEVCONTAINER_DOCKERFILE,
        r"devcontainers/python:[\d.]+$",
        f"devcontainers/python:{LATEST_PYTHON}",
    )
    rewrite(
        DEVCONTAINER_COMPOSE,
        r"image: postgres:\d+$",
        f"image: postgres:{LATEST_POSTGRES}",
    )

    lines = [
        f'{group_name(package, version)} = ["{requirement(package, version)}"]\n'
        for package, versions in supported.items()
        for version in versions
    ]
    rewrite(
        PYPROJECT,
        re.escape(GROUPS_COMMENT) + r"(?:(?:django|sqlalchemy)-[\d-]+ = .*\n)*",
        GROUPS_COMMENT + "".join(lines),
    )
    conflicts = "".join(
        "    ["
        + ", ".join(f'{{ group = "{group_name(package, v)}" }}' for v in versions)
        + "],\n"
        for package, versions in supported.items()
    )
    rewrite(
        PYPROJECT,
        r"^conflicts = \[\n(?:    .*\n)*\]\n",
        f"conflicts = [\n{conflicts}]\n",
    )
    rewrite(
        PRECOMMIT,
        r"django-upgrade --target-version [\d.]+",
        f"django-upgrade --target-version {supported['django'][0]}",
    )


@dataclasses.dataclass
class TestJob:
    python: str
    postgres: str
    # {package: version}
    versions: dict[str, str]


def test_matrix() -> list[TestJob]:
    groups = current_groups()
    return [
        TestJob(
            python=python,
            postgres=postgres,
            versions={
                package: versions[min(index, len(versions) - 1)]
                for package, versions in groups.items()
            },
        )
        for index, (python, postgres) in enumerate(
            zip(supported_python(), supported_postgres(), strict=True)
        )
    ]


def github_outputs() -> None:
    matrix = [
        {
            "python-version": job.python,
            "postgres-version": job.postgres,
            "groups": " ".join(
                f"--group {group_name(p, v)}" for p, v in job.versions.items()
            ),
        }
        for job in test_matrix()
    ]
    print(f"matrix={json.dumps({'include': matrix})}")
    print(f"postgres={LATEST_POSTGRES}")


def update() -> int:
    update_files()
    errors = []
    for job in test_matrix():
        django = job.versions["django"]
        needed = django_minimum_python(django)
        if version_key(job.python) < version_key(needed):
            errors.append(
                f"The Python {job.python} CI job would use Django {django}, "
                f"which needs Python {needed}"
            )
    for error in errors:
        print(error, file=sys.stderr)
    return 1 if errors else 0


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "command",
        choices=["update", "github-outputs"],
        help="update: rewrite every file that depends on the supported "
        "versions, and fail if the CI test matrix would use a Django that doesn't "
        "support its Python. github-outputs: print the CI test matrix and the latest "
        "PostgreSQL, as GitHub Actions step outputs.",
    )
    if parser.parse_args().command == "github-outputs":
        github_outputs()
        return 0
    return update()


if __name__ == "__main__":
    sys.exit(main())
